// native_net_register.cpp — registers every native of native_net_decl.h with
// bronze (embed::registerNative) under __bro_native.net. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_net from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.net.<Class>Proto for net.js to chain.

#include "native_net_decl.h"

#if BRO_WITH_NET

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_net(std::string* error) {
    const bool ok =
        fn("__bro_native.net.host", p(&bro_net_host), "void", {"i32", "dynamic"}, error) &&
        fn("__bro_native.net.unhost", p(&bro_net_unhost), "void", {}, error) &&
        fn("__bro_native.net.connect", p(&bro_net_connect), "i32", {"str", "i32", "dynamic"}, error) &&
        fn("__bro_native.net.disconnect", p(&bro_net_disconnect), "void", {"i32"}, error) &&
        fn("__bro_native.net.disconnectAll", p(&bro_net_disconnectAll), "void", {}, error) &&
        fn("__bro_native.net.send", p(&bro_net_send), "void", {"i32", "u8[]", "i32"}, error) &&
        fn("__bro_native.net.broadcast", p(&bro_net_broadcast), "void", {"u8[]", "i32"}, error) &&
        fn("__bro_native.net.peers", p(&bro_net_peers), "f64[]", {}, error) &&
        fn("__bro_native.net.getPeerAddress", p(&bro_net_getPeerAddress), "str", {"i32"}, error) &&
        fn("__bro_native.net.stats", p(&bro_net_stats), "str", {}, error) &&
        fn("__bro_native.net.getPeerStats", p(&bro_net_getPeerStats), "str", {"i32"}, error) &&
        fn("__bro_native.net.setPeerSimulatedLoss", p(&bro_net_setPeerSimulatedLoss), "void", {"i32", "f64", "f64", "f64"}, error);
    if (!ok) return false;
    return true;
}

}  // namespace bro::bronze_host

#else  // !(BRO_WITH_NET)

#include <string>

namespace bro::bronze_host {

// Compiled out: nothing is registered and net.js is not to be installed.
bool registerNatives_net(std::string*) { return true; }

}  // namespace bro::bronze_host

#endif  // BRO_WITH_NET
